class  NumberSeqModuleRental extends NumberSeqApplicationModule
{
    /*
    Detailed description of how to setup references for number sequences can
    be found i method loadModule() on the 'father' class: NumberSeqApplicationModule.
    */


}

Method.Source:
public void loadModule()
{
    NumberSeqDatatype datatype = NumberSeqDatatype::construct();

    /* Setup Vehicle id */
    datatype.parmDatatypeId(extendedtypenum(FMVehicleId));
    datatype.parmReferenceHelp(literalstr('FMVehicleID'));
    datatype.parmWizardIsContinuous(false);
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmSortField(1);

    //datatype.addParameterType(NumberSeqParameterType::OperatingUnit, true, false);
    this.create(datatype);


    /* Setup Rental id */
    datatype.parmDatatypeId(extendedtypenum(FMRentalId));
    datatype.parmReferenceHelp(literalstr('FMRentalID'));
    datatype.parmWizardIsContinuous(false);
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmSortField(1);

    //datatype.addParameterType(NumberSeqParameterType::, true, false);
    this.create(datatype);
}
